from functools import lru_cache

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        str_r = str(r)
        str_l = str(l - 1)
        digits_r = list(map(int, str_r))
        digits_l = list(map(int, str_l)) if l - 1 > 0 else []

        total = 0
        max_sum_r = 9 * len(digits_r)

        for target_sum in range(1, max_sum_r + 1):

            @lru_cache(None)
            def count_unbounded(rem_len: int, cur_sum: int, prod_mod: int, started: bool) -> int:
                if cur_sum > target_sum:
                    return 0
                if cur_sum + rem_len * 9 < target_sum:
                    return 0
                if rem_len == 0:
                    return int(started and cur_sum == target_sum and prod_mod == 0)

                ans = 0
                for d in range(10):
                    if not started and d == 0:
                        ans += count_unbounded(rem_len - 1, cur_sum, 1 % target_sum, False)
                    else:
                        next_sum = cur_sum + d
                        if next_sum <= target_sum:
                            next_prod = (prod_mod * d) % target_sum
                            ans += count_unbounded(rem_len - 1, next_sum, next_prod, True)
                return ans

            def solve_tight(pos: int, cur_sum: int, prod_mod: int, tight: bool, started: bool, digits: list) -> int:
                if cur_sum > target_sum:
                    return 0
                rem_len = len(digits) - pos
                if cur_sum + rem_len * 9 < target_sum:
                    return 0
                if not tight:
                    return count_unbounded(rem_len, cur_sum, prod_mod, started)
                if pos == len(digits):
                    return int(started and cur_sum == target_sum and prod_mod == 0)

                ans = 0
                limit = digits[pos] if tight else 9
                for d in range(limit + 1):
                    next_tight = tight and (d == limit)
                    if not started and d == 0:
                        ans += solve_tight(pos + 1, cur_sum, 1 % target_sum, next_tight, False, digits)
                    else:
                        next_sum = cur_sum + d
                        if next_sum <= target_sum:
                            next_prod = (prod_mod * d) % target_sum
                            ans += solve_tight(pos + 1, next_sum, next_prod, next_tight, True, digits)
                return ans

            ans_r = solve_tight(0, 0, 1 % target_sum, True, False, digits_r)
            ans_l = solve_tight(0, 0, 1 % target_sum, True, False, digits_l) if digits_l else 0
            total += ans_r - ans_l

        return total
